<?php
$month=(string)($_GET['month']??date('Y-m'));try{payrollMonth($month);}catch(DomainException){$month=date('Y-m');}$activity=employeeActivity($id,$month);
?><section class="panel padded commerce-block"><h2>Productivité & absences</h2><form method="get" class="filter-bar"><input type="hidden" name="page" value="employee_form"><input type="hidden" name="id" value="<?=$id?>"><label>Période<input type="month" name="month" value="<?=e($month)?>" required></label><button class="btn secondary">Afficher</button></form><div class="finance-summary"><div><span>Tâches terminées · mois sélectionné</span><strong><?=$activity['done']?></strong></div><div><span>Tâches ouvertes · actuellement</span><strong><?=$activity['open']?></strong></div><div><span>Ouvertes en retard · aujourd’hui</span><strong><?=$activity['late']?></strong></div><div><span>Jours présents renseignés</span><strong><?=$activity['counts']['Présent']?></strong></div><div><span>Jours d’absence renseignés</span><strong><?=$activity['counts']['Absent']?></strong></div><div><span>Congés renseignés</span><strong><?=$activity['counts']['Congé']?></strong></div><div><span>Heures de présence renseignées</span><strong><?=e(decimalString($activity['hours'],2))?> h</strong></div></div><p class="small muted">Suivi opérationnel des tâches actuellement attribuées et des journées saisies. Les jours sans pointage sont inconnus ; les heures sont des présences déclarées. Aucune note automatique ni retenue automatique pour absence.</p><div class="table-scroll"><table><thead><tr><th>DATE</th><th>SITUATION</th><th>HEURES</th><th>NOTE</th></tr></thead><tbody><?php foreach($activity['days'] as $day):?><tr><td><?=e($day['attendance_date'])?></td><td><?=e($day['state'])?></td><td><?=e($day['hours'])?></td><td><?=e($day['note'])?></td></tr><?php endforeach?></tbody></table></div><?php if(!$employee['archived']&&$employee['employment_state']==='Actif'):?><h3>Ajouter / corriger une journée</h3><form method="post" class="form-stack"><?=csrf()?><input type="hidden" name="action" value="attendance_save"><input type="hidden" name="return_employee" value="1"><input type="hidden" name="employee_id" value="<?=$id?>"><div class="form-grid"><?php inputField('Date','attendance_date',date('Y-m-d'),'date',true);selectField('Situation','state',['Présent','Absent','Congé'],'Absent');inputField('Heures · zéro pour absence / congé','hours','0.00','number',true,'min="0" max="24" step="0.01"');inputField('Note','note','','text',false,'maxlength="1000"');?></div><button class="btn secondary">Enregistrer la journée</button></form><?php endif?></section>
<section class="panel padded commerce-block"><h2>Fiches de paie</h2><p class="small muted">Brut = base + primes ; net = brut − cotisations − impôt − autres retenues saisis. Validez les montants avec votre gestionnaire de paie. L’émission n’effectue aucun versement.</p><a class="btn primary" href="<?=e(url('payroll_form',['employee_id'=>$id]))?>">Préparer une fiche de paie</a><div class="table-scroll"><table><thead><tr><th>MOIS</th><th>RÉFÉRENCE / ÉTAT</th><th class="numeric">NET À PAYER</th><th>PDF</th></tr></thead><tbody><?php foreach(all('SELECT * FROM payroll_records WHERE employee_id=? ORDER BY period DESC LIMIT 36',[$id]) as $pay):$pt=payrollTotals($pay);?><tr><td><a href="<?=e(url('payroll_form',['id'=>$pay['id']]))?>"><?=e($pay['period'])?></a></td><td><?=e($pay['number']?:$pay['state'])?></td><td class="numeric"><?=e(money(decimalString($pt['net'],2)))?></td><td><?php if($pay['state']==='Émis'):?><a href="<?=e(url('payroll_form',['id'=>$pay['id'],'download'=>'pdf']))?>">↓ PDF</a><?php endif?></td></tr><?php endforeach?></tbody></table></div><p class="small muted">36 périodes les plus récentes.</p></section>
<section class="panel padded commerce-block"><h2>Attestations de l’employé</h2><p class="small muted">Attestation de travail ou de salaire de base brut mensuel. Les informations émises sont conservées ; signature et cachet à apposer après vérification.</p><?php if(!$employee['archived']&&$employee['employment_state']==='Actif'):?><form method="post" class="form-stack"><?=csrf()?><input type="hidden" name="action" value="attestation_issue"><input type="hidden" name="employee_id" value="<?=$id?>"><input type="hidden" name="request_key" value="<?=e(bin2hex(random_bytes(32)))?>"><div class="form-grid"><label>Type<select name="kind"><option value="work">Attestation de travail</option><option value="salary">Attestation de salaire de base</option></select></label><?php inputField('Nom du signataire','signatory','','text',true,'maxlength="120"');inputField('Fait à · ville','place','','text',true,'maxlength="120"');?></div><label><input type="checkbox" name="facts_confirmed" value="1" required> Je certifie l’exactitude des informations de situation et de salaire.</label><button class="btn secondary">Émettre l’attestation</button></form><?php endif?><div class="table-scroll"><table><thead><tr><th>DOCUMENT</th><th>TYPE</th><th>DATE</th><th>PDF</th></tr></thead><tbody><?php foreach(all('SELECT id,kind,number,created_at FROM employee_documents WHERE employee_id=? ORDER BY id DESC LIMIT 50',[$id]) as $hrdoc):?><tr><td><a href="<?=e(url('hr_document',['id'=>$hrdoc['id']]))?>"><?=e($hrdoc['number'])?></a></td><td><?=$hrdoc['kind']==='work'?'Travail':'Salaire de base'?></td><td><?=e(localDate($hrdoc['created_at']))?></td><td><a href="<?=e(url('hr_document',['id'=>$hrdoc['id'],'download'=>'pdf']))?>">↓ PDF</a></td></tr><?php endforeach?></tbody></table></div><p class="small muted">50 attestations les plus récentes.</p></section>
